constexpr int MAXB = 40;
constexpr ll INF = 1000000010LL;

ll cappedPower(ll x, ll exponent) {
    ll result = 1;
    while (exponent--) {
        if (x != 0 && result > INF / x)
            return INF;
        result *= x;
        if (result >= INF)
            return INF;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

