    array<bool, MAXB> terminal{};

    for (ll i = MAXN - 1; i >= a; --i) {
        currentRow.fill(0);
        terminal.fill(false);

        ll power = 1;
        for (int j = 1; j < MAXB; ++j) {
            if (i != 0 && power > INF / i)
                power = INF;
            else
                power = min(INF, power * i);

            terminal[j] = (power >= n);
        }

        for (int j = MAXB - 1; j >= static_cast<int>(b); --j) {
