                currentRow[j] = ((MAXN - 1) % 2 == n % 2) ? 1 : 2;
            } else if (terminal[j]) {
                currentRow[j] = 1;
            } else {
                unsigned char right = (i + 1 < MAXN) ? nextRow[j] : 0;
                unsigned char up = (j + 1 < MAXB) ? currentRow[j + 1] : 0;

                if (right == 2 || up == 2)
