constexpr int MAXN = 1'000'010;
constexpr ll INF = 1'000'000'010LL;

ll cappedPower(ll x, ll exponent) {
    if (exponent == 0) return 1;
    if (exponent == 1) return min(x, INF);

    ll half = cappedPower(x, exponent / 2);
    __int128 result = (__int128)half * half;
    if (exponent & 1) result *= x;

    return result >= INF ? INF : static_cast<ll>(result);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b;
