        cout << "Stas";
        return 0;
    }

    constexpr unsigned char DRAW = 0;
    constexpr unsigned char WIN = 1;
    constexpr unsigned char LOSE = 2;

    array<unsigned char, 41> nextRow{}, currentRow{};

    for (int i = MAXN - 1; i >= a; --i) {
        int terminalExponent = 40;

        if (n <= INF) {
            ll value = 1;
            for (int j = 1; j < 40; ++j) {
