#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using State = unsigned char;

constexpr int MAXN = 1000000 + 10;
constexpr int MAX_EXP = 40;

bool powerAtLeast(ll base, ll exponent, ll target) {
    if (target <= 1) return true;

    __int128 result = 1;
    __int128 current = base;

    while (exponent > 0) {
        if (exponent & 1) {
            result *= current;
            if (result >= target) return true;
        }

        exponent >>= 1;
        if (exponent == 0) break;

        current *= current;
        if (current >= target) current = target;
    }

    return result >= target;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b, n;
    cin >> a >> b >> n;

    if (powerAtLeast(a, b, n)) {
        cout << "Stas";
        return 0;
    }

    if (a <= 0 || a >= MAXN || b <= 0 || b >= MAX_EXP) {
        cout << "Missing";
        return 0;
    }

    array<int, MAX_EXP> firstTerminal{};

    for (int exponent = 1; exponent < MAX_EXP; ++exponent) {
        if (!powerAtLeast(MAXN - 1, exponent, n)) {
            firstTerminal[exponent] = MAXN;
            continue;
        }

        int low = 1;
        int high = MAXN - 1;

        while (low < high) {
            int mid = low + (high - low) / 2;
            if (powerAtLeast(mid, exponent, n))
                high = mid;
            else
                low = mid + 1;
        }

        firstTerminal[exponent] = low;
    }

    vector<State> upper(MAXN, 0);
    vector<State> current(MAXN, 0);
    State answer = 0;

    for (int exponent = MAX_EXP - 1; exponent >= static_cast<int>(b);
         --exponent) {
        for (int base = MAXN - 1; base >= 1; --base) {
            if (n >= MAXN && exponent == 1 && base == MAXN - 1) {
                current[base] = ((MAXN - 1LL) % 2 == n % 2) ? 1 : 2;
                continue;
            }

            if (base >= firstTerminal[exponent]) {
                current[base] = 1;
                continue;
            }

            State right = (base + 1 < MAXN) ? current[base + 1] : 0;
            State up = (exponent + 1 < MAX_EXP) ? upper[base] : 0;

            if (right == 2 || up == 2) {
                current[base] = 1;
            } else if (base + 1 < MAXN && exponent + 1 < MAX_EXP &&
                       right == 1 && up == 1) {
                current[base] = 2;
            } else {
                current[base] = 0;
            }
        }

        if (exponent == b) {
            answer = current[static_cast<int>(a)];
            break;
        }

        upper.swap(current);
        fill(current.begin(), current.end(), 0);
    }

    if (answer == 0)
        cout << "Missing";
    else if (answer == 1)
        cout << "Masha";
    else
        cout << "Stas";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using State = unsigned char;

constexpr int MAXN = 1000000 + 10;
constexpr int MAXB = 40;
constexpr ll INF = 1000000010LL;

constexpr State WIN = 1;
constexpr State LOSE = 2;
constexpr State ONE_WINNING_MOVE = 3;

static State grid[MAXN][MAXB];

ll cappedMultiply(ll x, ll y) {
    return static_cast<__int128>(x) * y >= INF ? INF : x * y;
}

ll cappedPower(ll x, ll exponent) {
    ll result = 1;
    while (exponent > 0) {
        if (exponent & 1)
            result = cappedMultiply(result, x);
        exponent >>= 1;
        if (exponent)
            x = cappedMultiply(x, x);
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b, n;
    cin >> a >> b >> n;

    if (cappedPower(a, b) >= n) {
        cout << "Stas";
        return 0;
    }

    queue<uint32_t> q;

    for (int i = 1; i < MAXN; ++i) {
        ll power = 1;

        for (int j = 1; j < MAXB; ++j) {
            power = cappedMultiply(power, i);

            if (power >= n) {
                grid[i][j] = WIN;

                if ((i > 1 && grid[i - 1][j] == 0) ||
                    (j > 1 && grid[i][j - 1] == 0)) {
                    q.push(static_cast<uint32_t>(i * MAXB + j));
                }
            }
        }
    }

    if (n >= MAXN) {
        int i = MAXN - 1;
        int j = 1;
        grid[i][j] = ((i & 1) == (n & 1)) ? WIN : LOSE;
        q.push(static_cast<uint32_t>(i * MAXB + j));
    }

    while (!q.empty()) {
        uint32_t encoded = q.front();
        q.pop();

        int i = encoded / MAXB;
        int j = encoded % MAXB;

        for (int move = 0; move < 2; ++move) {
            int x = i - (move == 0);
            int y = j - (move == 1);

            if (x <= 0 || y <= 0)
                continue;

            State &previous = grid[x][y];

            if (grid[i][j] == LOSE) {
                if (previous == 0 || previous == ONE_WINNING_MOVE) {
                    previous = WIN;
                    q.push(static_cast<uint32_t>(x * MAXB + y));
                }
            } else {
                if (previous == 0) {
                    previous = ONE_WINNING_MOVE;
                } else if (previous == ONE_WINNING_MOVE) {
                    previous = LOSE;
                    q.push(static_cast<uint32_t>(x * MAXB + y));
                }
            }
        }
    }

    State result = grid[a][b];

    if (result == WIN)
        cout << "Masha";
    else if (result == LOSE)
        cout << "Stas";
    else
        cout << "Missing";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

constexpr int MAXN = 1000000 + 10;
constexpr long long INF = 1000000010LL;

unsigned char state[MAXN][40];
queue<uint32_t> q;

inline void push_state(int x, int y) {
    q.push(static_cast<uint32_t>(x * 40 + y));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b;
    long long n;
    cin >> a >> b >> n;

    auto capped_power = [](long long x, int exponent) {
        long long result = 1;
        while (exponent--) {
            if ((__int128)result * x >= INF)
                return INF;
            result *= x;
        }
        return result;
    };

    if (capped_power(a, b) >= n) {
        cout << "Stas";
        return 0;
    }

    for (int i = 1; i < MAXN; ++i) {
        long long value = 1;
        for (int j = 1; j < 40; ++j) {
            if ((__int128)value * i >= INF)
                value = INF;
            else
                value *= i;

            if (value >= n)
                state[i][j] = 1;
        }
    }

    if (n >= MAXN) {
        state[MAXN - 1][1] = ((MAXN - 1) % 2 == n % 2) ? 1 : 2;
    }

    for (int i = 1; i < MAXN; ++i) {
        for (int j = 1; j < 40; ++j) {
            if (state[i][j] != 0 &&
                ((i > 1 && state[i - 1][j] == 0) ||
                 (j > 1 && state[i][j - 1] == 0))) {
                push_state(i, j);
            }
        }
    }

    while (!q.empty()) {
        uint32_t encoded = q.front();
        q.pop();

        int i = encoded / 40;
        int j = encoded % 40;
        unsigned char current = state[i][j];

        if (i > 1) {
            unsigned char &previous = state[i - 1][j];

            if (current == 2) {
                if (previous == 0 || previous == 3) {
                    previous = 1;
                    push_state(i - 1, j);
                }
            } else {
                if (previous == 0) {
                    previous = 3;
                } else if (previous == 3) {
                    previous = 2;
                    push_state(i - 1, j);
                }
            }
        }

        if (j > 1) {
            unsigned char &previous = state[i][j - 1];

            if (current == 2) {
                if (previous == 0 || previous == 3) {
                    previous = 1;
                    push_state(i, j - 1);
                }
            } else {
                if (previous == 0) {
                    previous = 3;
                } else if (previous == 3) {
                    previous = 2;
                    push_state(i, j - 1);
                }
            }
        }
    }

    if (state[a][b] == 1)
        cout << "Masha";
    else if (state[a][b] == 2)
        cout << "Stas";
    else
        cout << "Missing";

    return 0;
}

